-- Módulo 36: inspecciones de calidad de los lotes de insumos recibidos de los proveedores (módulos 11 y 21).
CREATE TABLE "InspeccionesInsumos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Numero" character varying(20) NOT NULL,
    "ProductoId" integer NOT NULL,
    "ProveedorId" integer NOT NULL,
    "Lote" character varying(50) NOT NULL,
    "FechaInspeccion" date NOT NULL,
    "CantidadRecibida" numeric(18, 3) NOT NULL,
    "CantidadMuestra" numeric(18, 3) NOT NULL,
    "UnidadMedida" character varying(20) NOT NULL,
    "ToleranciaDefectosPorcentaje" numeric(5, 2) NOT NULL,
    "Inspector" character varying(100) NOT NULL,
    "Estado" character varying(10) NOT NULL,
    "CantidadDefectuosa" numeric(18, 3),
    "FechaDictamen" timestamp with time zone,
    "Observaciones" character varying(500),
    "MotivoAnulacion" character varying(250),
    CONSTRAINT "PK_InspeccionesInsumos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InspeccionesInsumos_Productos_ProductoId"
        FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InspeccionesInsumos_Proveedores_ProveedorId"
        FOREIGN KEY ("ProveedorId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_InspeccionesInsumos_Lote" CHECK (btrim("Lote") <> ''),
    CONSTRAINT "CK_InspeccionesInsumos_CantidadRecibida" CHECK ("CantidadRecibida" > 0),
    CONSTRAINT "CK_InspeccionesInsumos_CantidadMuestra"
        CHECK ("CantidadMuestra" > 0 AND "CantidadMuestra" <= "CantidadRecibida"),
    CONSTRAINT "CK_InspeccionesInsumos_UnidadMedida" CHECK (btrim("UnidadMedida") <> ''),
    CONSTRAINT "CK_InspeccionesInsumos_Tolerancia"
        CHECK ("ToleranciaDefectosPorcentaje" BETWEEN 0 AND 100),
    CONSTRAINT "CK_InspeccionesInsumos_Estado"
        CHECK ("Estado" IN ('Pendiente', 'Aprobada', 'Rechazada', 'Anulada')),
    CONSTRAINT "CK_InspeccionesInsumos_CantidadDefectuosa"
        CHECK ("CantidadDefectuosa" IS NULL OR ("CantidadDefectuosa" >= 0 AND "CantidadDefectuosa" <= "CantidadMuestra"))
);

CREATE UNIQUE INDEX "IX_InspeccionesInsumos_Numero"
    ON "InspeccionesInsumos" ("Numero");
CREATE INDEX "IX_InspeccionesInsumos_ProductoId"
    ON "InspeccionesInsumos" ("ProductoId");
CREATE INDEX "IX_InspeccionesInsumos_ProveedorId"
    ON "InspeccionesInsumos" ("ProveedorId");
CREATE INDEX "IX_InspeccionesInsumos_FechaInspeccion"
    ON "InspeccionesInsumos" ("FechaInspeccion");
CREATE INDEX "IX_InspeccionesInsumos_Estado"
    ON "InspeccionesInsumos" ("Estado");
-- Un mismo producto y proveedor no tiene dos inspecciones no anuladas del mismo lote.
CREATE UNIQUE INDEX "IX_InspeccionesInsumos_ProductoId_ProveedorId_Lote"
    ON "InspeccionesInsumos" ("ProductoId", "ProveedorId", "Lote") WHERE "Estado" <> 'Anulada';
